start","alignItems":"center"}},{"id":"schedule_icon","component":"Image","src":"{{ ${/asset/scheduleIcon} }}","styles":{"width":16,"height":16,"objectFit":"contain"}},{"id":"schedule_text","component":"Text","content":"{{ ${/data/calendar/items/0/dtStart} + ' ' + ${/data/calendar/items/0/title} }}","styles":{"width":78,"height":14,"fontSize":12,"fontWeight":500,"fontColor":"#ffffffff","maxLines":1,"textOverflow":"none","textAlign":"start"}},{"id":"action_pill","component":"Row","children":["action_icon","action_label"],"itemMargin":6,"onClick":[{"call":"clickToDeeplink","args":{"bundleName":"com.huawei.hmos.settings","abilityName":"com.huawei.hmos.settings.MainAbility","uri":"storage_settings"}}],"styles":{"width":116,"height":26,"padding":{"left":12,"right":12},"borderRadius":13,"backgroundColor":"#ff64bb5c","justifyContent":"center","alignItems":"center"}},{"id":"action_icon","component":"Image","src":"{{ ${/asset/actionIcon} }}","styles":{"width":16,"height":16,"objectFit":"contain"}},{"id":"action_label","component":"Text","content":"{{ ${/action/label} }}","styles":{"width":58,"height":18,"fontSize":14,"fontWeight":600,"fontColor":"#ffffffff","maxLines":1,"textOverflow":"none","textAlign":"center"}}]}}
